// «Docker турших самбар». Энэ файлыг өөрчлөх шаардлагагүй.
const output = document.getElementById("output");
function panel(cls, testid, title, lines) {
  const box = document.createElement("section");
  box.className = "call " + cls;
  box.dataset.testid = testid;
  const h = document.createElement("h2");
  h.textContent = title;
  box.append(h);
  for (const line of lines) {
    const p = document.createElement("pre");
    p.textContent = line;
    box.append(p);
  }
  output.append(box);
  return box;
}

const dockerfile = [
  { instruction: "FROM", arg: "node:20" },
  { instruction: "COPY", arg: ". /app" },
  { instruction: "RUN", arg: "npm install" },
  { instruction: "CMD", arg: "npm start" },
];

window.IMAGE = null;
try {
  window.IMAGE = buildImage(dockerfile);
  panel("ok", "image", "Угсарсан image", [JSON.stringify(window.IMAGE, null, 2)]);
} catch (problem) {
  panel("bad", "error", "Алдаа", [problem.message]);
}
document.body.dataset.ready = "1";

