function buildImage(dockerfile) {
  let base = null;
  let cmd = null;
  const layers = [];

  for (const step of dockerfile) {
    if (step.instruction === "FROM") base = step.arg;
    else if (step.instruction === "CMD") cmd = step.arg;
    else layers.push({ instruction: step.instruction, arg: step.arg });
  }

  return { base: base, layers: layers, cmd: cmd };
}
